public class Question_06{static class Node{int id;Node l,r;Node(int x){id=x;}}static Node add(Node n,int x){if(n==null)return new Node(x);if(x<n.id)n.l=add(n.l,x);else if(x>n.id)n.r=add(n.r,x);return n;}static boolean has(Node n,int x){if(n==null)return false;if(n.id==x)return true;return x<n.id?has(n.l,x):has(n.r,x);}static void in(Node n){if(n!=null){in(n.l);System.out.print(n.id+" ");in(n.r);}}static void pre(Node n){if(n!=null){System.out.print(n.id+" ");pre(n.l);pre(n.r);}}static void post(Node n){if(n!=null){post(n.l);post(n.r);System.out.print(n.id+" ");}}public static void main(String[]x){int[]a={50,30,70,20,40,60,80};Node r=null;for(int v:a)r=add(r,v);System.out.print("Inorder: ");in(r);System.out.print("\nPreorder: ");pre(r);System.out.print("\nPostorder: ");post(r);System.out.println("\nClaim 60 found: "+has(r,60));}}